<script setup>
import { computed, onMounted, ref } from 'vue';
import { verificationService } from '../services';
import { createLogger, logException } from '../utils/logger';

const logger = createLogger('VerificationReviewView');
const rows = ref([]); const loading = ref(false); const error = ref(''); const status = ref('pending'); const selected = ref(null); const rejectionReason = ref(''); const reviewing = ref(false);
const filteredRows = computed(() => rows.value.filter((row) => !status.value || row.status === status.value));
async function load() { loading.value = true; error.value = ''; try { const response = await verificationService.list({ status: status.value }); rows.value = response.data || []; } catch (exception) { error.value = 'دریافت پرونده‌های احراز هویت انجام نشد.'; logger.error('load', 'Verification queue failed', logException(exception)); } finally { loading.value = false; } }
async function openDetails(row) { try { const response = await verificationService.get(row.id); selected.value = response.data; } catch (exception) { error.value = 'جزئیات پرونده دریافت نشد.'; logger.error('openDetails', 'Verification details failed', logException(exception)); } }
async function review(nextStatus) { if (!selected.value || reviewing.value) return; reviewing.value = true; try { await verificationService.review(selected.value.id, { status: nextStatus, rejection_reason: nextStatus === 'rejected' ? rejectionReason.value : null }); selected.value = null; rejectionReason.value = ''; await load(); } catch (exception) { error.value = exception.response?.data?.message || 'ثبت نتیجه بررسی انجام نشد.'; logger.error('review', 'Verification review failed', logException(exception)); } finally { reviewing.value = false; } }
onMounted(load);
</script>

<template>
<section class="review-view" dir="rtl"><header class="review-header"><div><span>مرکز بررسی</span><h1>احراز هویت کاربران</h1><p>پرونده‌های ارسالی را بررسی و نتیجه را ثبت کنید.</p></div><select v-model="status" @change="load"><option value="pending">در انتظار بررسی</option><option value="approved">تایید شده</option><option value="rejected">رد شده</option><option value="">همه پرونده‌ها</option></select></header><p v-if="error" class="review-error" role="alert">{{ error }}</p><div v-if="loading" class="review-loading">در حال دریافت پرونده‌ها...</div><div v-else-if="!filteredRows.length" class="review-empty"><i class="pi pi-inbox"></i><p>پرونده‌ای در این وضعیت وجود ندارد.</p></div><div v-else class="review-table"><article v-for="row in filteredRows" :key="row.id" class="review-row"><div><strong>{{ row.user?.name || 'بدون نام' }}</strong><span>{{ row.user?.mobile }}، کد ملی {{ row.national_code }}</span></div><b :class="`status-${row.status}`">{{ row.status === 'pending' ? 'در انتظار بررسی' : row.status === 'approved' ? 'تایید شده' : 'رد شده' }}</b><button type="button" @click="openDetails(row)"><i class="pi pi-eye"></i>مشاهده پرونده</button></article></div><div v-if="selected" class="review-overlay"><section class="review-dialog"><header><h2>جزئیات پرونده #{{ selected.id }}</h2><button type="button" aria-label="بستن" @click="selected = null"><i class="pi pi-times"></i></button></header><dl class="review-details"><div><dt>نام</dt><dd>{{ selected.user?.name }}</dd></div><div><dt>کد ملی</dt><dd>{{ selected.national_code }}</dd></div><div><dt>تلفن ثابت</dt><dd>{{ selected.home_phone }}</dd></div><div><dt>شبا</dt><dd dir="ltr">{{ selected.iban }}</dd></div><div class="wide"><dt>آدرس</dt><dd>{{ selected.postal_address }}</dd></div></dl><div class="review-documents"><a v-for="(url, name) in selected.documents" :key="name" :href="url" target="_blank"><i class="pi pi-file"></i>{{ name }}</a></div><textarea v-if="selected.status === 'pending'" v-model="rejectionReason" placeholder="دلیل رد پرونده، در صورت نیاز"></textarea><footer v-if="selected.status === 'pending'"><button type="button" class="danger-action" :disabled="reviewing" @click="review('rejected')">رد پرونده</button><button type="button" class="approve-action" :disabled="reviewing" @click="review('approved')">تایید هویت</button></footer></section></div></section>
</template>

<style scoped>
.review-view{direction:rtl}.review-header{display:flex;align-items:end;justify-content:space-between;gap:20px;margin-bottom:22px}.review-header span{color:#a62626;font-size:11px;font-weight:700}.review-header h1{margin:7px 0 5px;color:#202a35;font-size:24px}.review-header p{margin:0;color:#78848c;font-size:12px}.review-header select{min-width:170px;padding:10px;border:1px solid #dfe4e8;border-radius:7px;background:#fff;font:inherit;font-size:11px}.review-error{padding:10px;border-right:3px solid #b83232;background:#fff5f3;color:#963b35;font-size:12px}.review-table{display:grid;gap:10px}.review-row{display:grid;grid-template-columns:minmax(0,1fr) auto auto;align-items:center;gap:18px;padding:16px;border:1px solid #edf0f2;border-radius:10px;background:#fff}.review-row strong,.review-row span{display:block}.review-row span{margin-top:5px;color:#78848c;font-size:11px}.review-row b{padding:6px 9px;border-radius:14px;font-size:10px;font-weight:500}.status-pending{background:#fff6e6;color:#a56824}.status-approved{background:#ecf8f1;color:#287b50}.status-rejected{background:#fff0ef;color:#ae4747}.review-row button{padding:8px 11px;border:1px solid #dfe4e8;border-radius:7px;background:#fff;color:#52616b;cursor:pointer;font:inherit;font-size:11px}.review-loading,.review-empty{padding:60px;text-align:center;color:#78848c}.review-empty i{font-size:28px}.review-overlay{position:fixed;inset:0;z-index:120;display:grid;place-items:center;padding:16px;background:rgba(32,42,53,.5)}.review-dialog{width:min(720px,100%);max-height:calc(100vh - 32px);overflow:auto;border-radius:12px;background:#fff}.review-dialog>header{display:flex;align-items:center;justify-content:space-between;padding:18px 22px;border-bottom:1px solid #edf0f2}.review-dialog h2{margin:0;color:#202a35;font-size:17px}.review-dialog header button{border:0;background:transparent;color:#71808c;cursor:pointer}.review-details{display:grid;grid-template-columns:1fr 1fr;gap:14px;padding:20px 22px;margin:0}.review-details div{min-width:0}.review-details .wide{grid-column:1/-1}.review-details dt{color:#89959c;font-size:10px}.review-details dd{margin:4px 0 0;color:#37464f;font-size:12px}.review-documents{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;padding:0 22px}.review-documents a{padding:10px;border:1px solid #e1e7e9;border-radius:7px;color:#a62626;text-decoration:none;font-size:10px}.review-dialog textarea{width:calc(100% - 44px);min-height:80px;margin:20px 22px 0;padding:10px;border:1px solid #dfe4e8;border-radius:7px;font:inherit;font-size:11px}.review-dialog footer{display:flex;justify-content:flex-start;gap:8px;padding:20px 22px}.danger-action,.approve-action{padding:10px 16px;border:0;border-radius:7px;color:#fff;cursor:pointer;font:inherit;font-size:11px}.danger-action{background:#a62626}.approve-action{background:#287b50}@media(max-width:650px){.review-header{align-items:stretch;flex-direction:column}.review-row{grid-template-columns:1fr}.review-documents{grid-template-columns:1fr}.review-details{grid-template-columns:1fr}.review-details .wide{grid-column:auto}}
</style>
